-- create "rte_credit_balances" table
CREATE TABLE "rte_credit_balances" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "namespace" character varying NOT NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "deleted_at" timestamptz NULL,
  "customer_id" character(26) NOT NULL,
  "currency_key" character varying NOT NULL,
  "feature_scope" character varying NOT NULL,
  "calculated_at" timestamptz NOT NULL,
  "booked" numeric NOT NULL,
  "spendable" numeric NOT NULL,
  "live" numeric NOT NULL,
  "pending" numeric NOT NULL,
  PRIMARY KEY ("id")
);
-- create index "rte_credit_balance_scope" to table: "rte_credit_balances"
CREATE UNIQUE INDEX "rte_credit_balance_scope" ON "rte_credit_balances" ("namespace", "customer_id", "currency_key", "feature_scope") WHERE (deleted_at IS NULL);
-- create index "rtecreditbalance_namespace" to table: "rte_credit_balances"
CREATE INDEX "rtecreditbalance_namespace" ON "rte_credit_balances" ("namespace");
